async function fileExists(filepath: string) {
  return fs.access(filepath).then(
    () => true,
    () => false,
  );
}

async function isDirectory(path: string) {
  if (await fileExists(path)) {
    const stats = await fs.stat(path);
    return stats.isDirectory();
  }

  return false;
}

